  function metrics(){return Domain.metrics(appState,{year:NOW_YEAR,month:CURRENT_MONTH})}
  function renderMetrics(){const m=metrics();els.yearWatched.textContent=m.yearWatched;els.wantCount.textContent=m.want;els.planCount.textContent=m.plans;els.planDone.textContent=m.done;els.totalCount.textContent=m.total;const pct=m.plans?Math.round(m.done/m.plans*100):0;els.planTopDone.textContent=m.done;els.planTopAll.textContent=m.plans;els.planPercent.textContent=pct+'%';els.planBar.style.width=pct+'%';if(els.yearCompareNote){const delta=m.yearWatched-m.prevYearWatched;els.yearCompareNote.textContent=m.prevYearWatched?`较去年 ${delta>=0?'+':''}${delta}`:(m.yearWatched?'去年暂无记录':'今年还没有观看记录')}if(els.homeHeroYear)els.homeHeroYear.textContent=NOW_YEAR;if(els.homePlanMonthLabel)els.homePlanMonthLabel.textContent=monthLabel(CURRENT_MONTH);if(els.batchPlan)els.batchPlan.textContent=`加入 ${monthLabel(CURRENT_MONTH)}`}
