  function renderRecent(){els.recentGrid.innerHTML='';const rows=watchEntries().filter(x=>x.watch.date).sort((a,b)=>String(b.watch.date).localeCompare(String(a.watch.date))).slice(0,4);if(!rows.length){els.recentGrid.innerHTML='<div class="home-radar-empty"><div><b>还没有真实观看记录</b>记录第一次观看后，这里会显示最近的作品、日期与评分。</div></div>';return}rows.forEach(({movie,watch})=>{const el=document.createElement('article');el.className='recent';el.dataset.openDetail=movie.id;el.style.cursor='pointer';const d=String(watch.date).slice(5).replace('-','月')+'日',season=isSeasonSourceWatch(movie,watch)?` · 第 ${watch.sourceSeason} 季豆瓣标记`:'';const posterUrl=String(movie.info.posterUrl||'').trim();el.innerHTML=`<div class="mini-poster${posterUrl?' has-image':''}" role="img" aria-label="${escAttr(movie.info.title)} 海报"></div><div><div class="t">${esc(movie.info.title)}</div><div class="d">${esc(d+season)}</div><div class="r">${watch.rating!=null?'★ '+Number(watch.rating).toFixed(1):'未评分'}</div></div>`;const p=el.querySelector('.mini-poster');if(p&&posterUrl)p.style.backgroundImage=`url(${JSON.stringify(posterUrl)})`;els.recentGrid.appendChild(el)})}
  function renderPlan(){els.planList.innerHTML='';const entries=planEntries(CURRENT_MONTH).filter(x=>x.plan.status!=='deferred').sort((a,b)=>String(a.plan.plannedDate||'9999').localeCompare(String(b.plan.plannedDate||'9999'))).slice(0,4);if(!entries.length){els.planList.innerHTML='<div class="plan-row"><span>本月还没有观影计划</span><span class="date">—</span><span class="status wait">待安排</span></div>';return}entries.forEach(({movie,plan})=>{const el=document.createElement('div');el.className='plan-row';const date=plan.plannedDate?plan.plannedDate.slice(5):'待定';el.innerHTML=`<span>${esc(movie.info.title)}</span><span class="date">${esc(date)}</span><span class="status ${plan.status==='completed'?'done':'wait'}">${plan.status==='completed'?'已看':plan.status==='deferred'?'延期':'待看'}</span>`;el.style.cursor='pointer';el.dataset.openDetail=movie.id;els.planList.appendChild(el)})}
  const homeRandomState={movieId:null,recentIds:[]};
  function randomCandidates(){const all=(appState.movies||[]).filter(m=>m.personal?.status==='want'&&!(m.watchHistory||[]).length&&m.info?.title),ids=Array.isArray(appState.home?.featured)?appState.home.featured:[],featured=ids.map(id=>all.find(m=>m.id===id)).filter(Boolean);return featured.length?featured:all}
  function pickRandomMovie(forceNew=false){const list=randomCandidates();if(!list.length){homeRandomState.movieId=null;return null}let current=list.find(m=>m.id===homeRandomState.movieId);if(current&&!forceNew)return current;let pool=list.filter(m=>m.id!==homeRandomState.movieId&&!homeRandomState.recentIds.includes(m.id));if(!pool.length)pool=list.filter(m=>m.id!==homeRandomState.movieId);if(!pool.length)pool=list;const next=pool[Math.floor(Math.random()*pool.length)];if(next){if(homeRandomState.movieId)homeRandomState.recentIds=[homeRandomState.movieId,...homeRandomState.recentIds].slice(0,6);homeRandomState.movieId=next.id}return next||null}
