    els.randomTitle.textContent=i.title||'未命名电影';const meta=[];if(i.originalTitle&&i.originalTitle!==i.title)meta.push(i.originalTitle);if(i.year)meta.push(i.year);if((i.genres||[]).length)meta.push((i.genres||[]).slice(0,2).join(' / '));if(i.runtime)meta.push(`${i.runtime} 分钟`);els.randomMeta.textContent=meta.join(' · ')||'资料待补全';
