    function batchTmdbUpdateUi(text='',pct=0){const p=Math.max(0,Math.min(100,Math.round(pct)));els.batchTmdbInline.classList.toggle('hidden',!batchTmdbState.running);els.batchTmdbInlineText.textContent=text||'正在处理…';els.batchTmdbInlineBar.style.width=p+'%';els.batchTmdbProgressText.textContent=text||'准备开始';els.batchTmdbProgressPct.textContent=p+'%';els.batchTmdbProgressBar.style.width=p+'%';els.batchTmdbBtn.disabled=batchTmdbState.running;els.batchTmdbStop.disabled=!batchTmdbState.running}
