  async function resolveBatchTmdbCandidate(movieId,tmdbId,tmdbType){const movie=appState.movies.find(m=>m.id===movieId);if(!movie)return;const btn=els.batchTmdbPending.querySelector(`[data-batch-tmdb-candidate="${CSS.escape(movieId)}"][data-tmdb-id="${CSS.escape(String(tmdbId))}"]`);if(btn)btn.disabled=true;try{const row=batchTmdbState.pending.find(x=>x.movieId===movieId),candidate=(row?.candidates||[]).find(c=>String(c.id)===String(tmdbId)&&(!tmdbType||(c.media_type||'movie')===tmdbType)),bundle=await fetchTmdbBundle(tmdbId,candidate?.media_type||tmdbType||movie.mediaType);applyTmdbBundleToMovie(movie,bundle);if(bundle.mediaType==='tv')collapseTvSeriesForMovie(movie,bundle);batchTmdbState.pending=batchTmdbState.pending.filter(x=>x.movieId!==movieId);batchTmdbState.completed++;save();renderAll();renderBatchTmdbPending();toastMsg(`《${movie.info.title}》已完成 TMDb 补全`)}catch(err){toastMsg(`补全失败：${err.message}`)}finally{if(btn)btn.disabled=false}}
