  async function searchTmdbMovie(){const q=(els.tmdbMovieQuery.value||els.movieTitleInput.value).trim();if(!q){setTmdbSearchState('请输入片名。','bad');return}appState.settings.tmdbLanguage=els.settingsTmdbLanguage?.value||appState.settings.tmdbLanguage||'zh-CN';setTmdbSearchState('正在搜索 TMDb…');els.tmdbMovieSearchBtn.disabled=true;try{const type=els.movieMediaTypeInput.value==='tv'?'tv':'movie',year=els.movieYearInput.value.trim(),params={query:q,include_adult:false,language:appState.settings.tmdbLanguage||'zh-CN',page:1};if(year)params[type==='tv'?'first_air_date_year':'primary_release_year']=year;const data=await tmdbFetch(type==='tv'?'/search/tv':'/search/movie',params);const results=(data.results||[]).slice(0,8).map(x=>({...x,media_type:type}));renderTmdbCandidates(results);setTmdbSearchState(results.length?`找到 ${results.length} 个${type==='tv'?'剧集':'电影'}候选，请选择正确作品。`:`没有找到匹配${type==='tv'?'剧集':'电影'}，可以尝试原名或清空年份。`,results.length?'ok':'bad')}catch(err){renderTmdbCandidates([]);setTmdbSearchState(`搜索失败：${err.message}`,'bad')}finally{els.tmdbMovieSearchBtn.disabled=false}}
  async function applyTmdbMovie(tmdbId,mediaType){setTmdbSearchState('正在读取作品详情与主创信息…');els.tmdbMovieSearchBtn.disabled=true;try{const type=mediaType==='tv'?'tv':'movie',bundle=await fetchTmdbBundle(tmdbId,type),d=bundle.detail||{},tmp=normalizeMovie({mediaType:type,info:{}});applyTmdbBundleToMovie(tmp,bundle,{overwrite:true});els.movieMediaTypeInput.value=type;updateMovieModalType();els.movieTitleInput.value=tmp.info.title||candidateTitle({...d,media_type:type})||'';els.movieOriginalTitleInput.value=tmp.info.originalTitle||'';els.movieYearInput.value=tmp.info.year||'';els.movieReleaseDateInput.value=tmp.info.releaseDate||'';els.movieLastAirDateInput.value=tmp.info.lastAirDate||'';els.movieRuntimeInput.value=tmp.info.runtime||'';els.movieSeasonsInput.value=tmp.info.numberOfSeasons??'';els.movieEpisodesInput.value=tmp.info.numberOfEpisodes??'';els.movieTvStatusInput.value=tmp.info.tvStatus||'';els.movieTmdbIdInput.value=d.id||tmdbId;els.movieDirectorInput.value=(tmp.info.directors||[]).join(' / ');els.movieCountryInput.value=(tmp.info.countries||[]).join(' / ');els.movieGenresInput.value=(tmp.info.genres||[]).join(' / ');els.movieOverviewInput.value=tmp.info.overview||'';els.moviePosterInput.value=tmp.info.posterUrl||'';els.tmdbMovieQuery.value=tmp.info.title||'';renderTmdbCandidates([]);setTmdbSearchState(`已关联 ${type==='tv'?'TV':'Movie'} · TMDb #${d.id}，保存后写入影视库。`,'ok')}catch(err){setTmdbSearchState(`补全失败：${err.message}`,'bad')}finally{els.tmdbMovieSearchBtn.disabled=false}}
