  function normalizeBulkTitleLine(line){let v=String(line||'').trim();v=v.replace(/^\s*(?:(?:[-*•]+)|(?:\d+[.、)）])|(?:[（(]\d+[）)]))\s*/,'').trim();v=v.replace(/^《(.+)》$/,'$1').trim();return v}
  function parseBulkTitles(raw){const seen=new Set(),rows=[];for(const line of String(raw||'').split(/\r?\n/)){const clean=normalizeBulkTitleLine(line);if(!clean)continue;const pair=doubanParseTitlePair(clean),title=String(pair.title||'').trim(),originalTitle=String(pair.originalTitle||'').trim();if(!title)continue;const key=cleanTmdbTitle(originalTitle||title);if(!key||seen.has(key))continue;seen.add(key);rows.push({title,originalTitle})}return rows}
  function bulkTitleExisting(row){
    const t=cleanTmdbTitle(row.title),o=cleanTmdbTitle(row.originalTitle);
    return (appState.movies||[]).find(m=>{const mt=cleanTmdbTitle(m.info?.title),mo=cleanTmdbTitle(m.info?.originalTitle);return (t&&(t===mt||t===mo))||(o&&(o===mt||o===mo))})||null;
  }
  function makeBulkTitleMovie(row){return normalizeMovie({id:uid(),mediaType:'unknown',info:{title:row.title,originalTitle:row.originalTitle},personal:{status:'want',rating:null,tags:[],shortReview:'',favorite:false},watchHistory:[],plans:[],radar:{discovered:false,ignored:false}})}
