  function hexToRgb(hex){const v=String(hex||'#9f7cff').replace('#','');if(!/^[0-9a-fA-F]{6}$/.test(v))return {r:159,g:124,b:255};return {r:parseInt(v.slice(0,2),16),g:parseInt(v.slice(2,4),16),b:parseInt(v.slice(4,6),16)}}
