  function legacySeedIndex(movie){const m=String(movie?.id||'').match(/^demo-(\d+)$/);return m?Number(m[1]):null}
  function legacySeedSyntheticDate(index){if(!index||!(index in LEGACY_SEED_RATINGS))return'';return `2026-${String(((index-1)%7)+1).padStart(2,'0')}-${String((((index-1)*3)%27)+1).padStart(2,'0')}`}
  function legacySeedCleanupPreview(){let legacyMovies=0,syntheticWatches=0,syntheticPlans=0;for(const m of (appState.movies||[])){const i=legacySeedIndex(m);if(!i)continue;legacyMovies++;const d=legacySeedSyntheticDate(i),r=LEGACY_SEED_RATINGS[i];syntheticWatches+=(m.watchHistory||[]).filter(w=>d&&String(w.date||'')===d&&Number(w.rating)===Number(r)&&!String(w.venue||'').trim()&&!String(w.note||'').trim()&&!w.sourceDoubanId).length;const seedMonth=String(m.createdAt||'').slice(0,7);if(seedMonth&&['demo-12','demo-19','demo-20','demo-26'].includes(m.id))syntheticPlans+=(m.plans||[]).filter(p=>p.month===seedMonth&&!p.plannedDate&&((m.id==='demo-19'||m.id==='demo-20')?p.status==='completed':p.status==='planned')).length}return{legacyMovies,syntheticWatches,syntheticPlans}}
  function updateLegacySeedStatus(){if(!els.settingsLegacySeedStatus)return;const x=legacySeedCleanupPreview();els.settingsLegacySeedStatus.className='tmdb-status '+((x.syntheticWatches+x.syntheticPlans)?'bad':'ok');els.settingsLegacySeedStatus.textContent=x.legacyMovies?`检测到 ${x.legacyMovies} 条旧版演示来源作品；其中可安全清理 ${x.syntheticWatches} 条虚构观看记录、${x.syntheticPlans} 条演示计划。作品本体不会删除。`:'没有检测到旧版演示来源记录。'}
  function cleanupLegacySeedArtifacts(){const x=legacySeedCleanupPreview();if(!(x.syntheticWatches+x.syntheticPlans)){updateLegacySeedStatus();toastMsg('没有可安全清理的旧版演示痕迹');return}if(!confirm(`将删除 ${x.syntheticWatches} 条可精确识别的旧演示观看记录和 ${x.syntheticPlans} 条演示计划。\n\n不会删除作品本体、豆瓣导入记录或 TMDb 资料。继续吗？`))return;let watches=0,plans=0;for(const m of (appState.movies||[])){const i=legacySeedIndex(m);if(!i)continue;const d=legacySeedSyntheticDate(i),r=LEGACY_SEED_RATINGS[i],before=(m.watchHistory||[]).length;m.watchHistory=(m.watchHistory||[]).filter(w=>!(d&&String(w.date||'')===d&&Number(w.rating)===Number(r)&&!String(w.venue||'').trim()&&!String(w.note||'').trim()&&!w.sourceDoubanId));watches+=before-m.watchHistory.length;const seedMonth=String(m.createdAt||'').slice(0,7);if(seedMonth&&['demo-12','demo-19','demo-20','demo-26'].includes(m.id)){const pb=(m.plans||[]).length;m.plans=(m.plans||[]).filter(p=>!(p.month===seedMonth&&!p.plannedDate&&((m.id==='demo-19'||m.id==='demo-20')?p.status==='completed':p.status==='planned')));plans+=pb-m.plans.length}if(before!==m.watchHistory.length)m.updatedAt=new Date().toISOString()}save();renderAll();renderSettings();toastMsg(`已清理 ${watches} 条旧演示观看记录与 ${plans} 条演示计划`) }

