  async function testTmdbConnection(){appState.settings.tmdbLanguage=els.settingsTmdbLanguage.value||'zh-CN';els.settingsTmdbStatus.className='tmdb-status';els.settingsTmdbStatus.textContent='正在连接 TMDb 资料服务…';try{await tmdbFetch('/configuration');els.settingsTmdbStatus.className='tmdb-status ok';els.settingsTmdbStatus.textContent='连接成功。TMDb 资料服务已可直接用于搜索、批量补全和电影雷达。'}catch(err){els.settingsTmdbStatus.className='tmdb-status bad';els.settingsTmdbStatus.textContent=`连接失败：${err.message||'代理服务异常'}。`}}

  async function runTmdbSelfTest(){
    appState.settings.tmdbLanguage=els.settingsTmdbLanguage.value||'zh-CN';
    const btn=els.settingsSelfTestTmdb;btn.disabled=true;
    const lines=[];const show=(ok=false)=>{els.settingsTmdbStatus.className='tmdb-status'+(ok?' ok':'');els.settingsTmdbStatus.textContent=lines.join('\n')};
    const step=(msg)=>{lines.push('… '+msg);show(false)};
    const pass=(msg)=>{lines[lines.length-1]='✓ '+msg;show(false)};
    const fail=(msg,err)=>{lines[lines.length-1]='✕ '+msg+'：'+(err?.message||err||'未知错误');els.settingsTmdbStatus.className='tmdb-status bad';els.settingsTmdbStatus.textContent=lines.join('\n')};
    try{
      step('1/5 凭证与 TMDb API 连通性');
      const config=await tmdbFetch('/configuration');
      if(!config?.images?.secure_base_url)throw new Error('configuration 返回异常');
      pass('1/5 API 连通，凭证有效');

      step('2/5 搜索接口（测试词：The Matrix）');
      const search=await tmdbFetch('/search/movie',{query:'The Matrix',include_adult:false,language:appState.settings.tmdbLanguage||'zh-CN'});
      const hit=(search?.results||[]).find(x=>x.id)||search?.results?.[0];
      if(!hit?.id)throw new Error('搜索未返回电影结果');
      pass(`2/5 搜索成功，命中 TMDb #${hit.id} · ${hit.title||hit.original_title||'电影'}`);

      step('3/5 电影详情接口');
      const detail=await tmdbFetch(`/movie/${hit.id}`,{language:appState.settings.tmdbLanguage||'zh-CN'});
      if(!detail?.id||!detail?.title)throw new Error('详情字段不完整');
      pass(`3/5 详情成功 · ${detail.title}${detail.runtime?` · ${detail.runtime} 分钟`:''}`);

      step('4/5 演职员接口 / 导演识别');
      const credits=await tmdbFetch(`/movie/${hit.id}/credits`,{language:appState.settings.tmdbLanguage||'zh-CN'});
      const directors=(credits?.crew||[]).filter(x=>x.job==='Director').map(x=>x.name).filter(Boolean);
      if(!directors.length)throw new Error('未识别到导演');
      pass(`4/5 演职员成功 · 导演：${directors.join(' / ')}`);

      step('5/5 海报 CDN');
      if(!detail.poster_path)throw new Error('测试电影没有 poster_path');
      const poster=tmdbImage(detail.poster_path,'w185');
      await new Promise((resolve,reject)=>{const img=new Image();const timer=setTimeout(()=>reject(new Error('海报加载超时')),8000);img.onload=()=>{clearTimeout(timer);resolve()};img.onerror=()=>{clearTimeout(timer);reject(new Error('image.tmdb.org 加载失败'))};img.src=poster});
      pass('5/5 海报 CDN 加载成功');

      lines.push('✓ 完整自检通过：搜索 → 详情 → 导演 → 海报链路均可用。');
      els.settingsTmdbStatus.className='tmdb-status ok';els.settingsTmdbStatus.textContent=lines.join('\n');
      save();toastMsg('TMDb 完整自检通过');
    }catch(err){
      if(lines.length && lines[lines.length-1].startsWith('…'))fail(lines[lines.length-1].replace(/^…\s*/,''),err);
      else{lines.push('✕ 自检失败：'+(err?.message||err));els.settingsTmdbStatus.className='tmdb-status bad';els.settingsTmdbStatus.textContent=lines.join('\n')}
    }finally{btn.disabled=false}
  }

  function toggleDetailPlan(){const m=currentDetailMovie();if(!m)return;const plan=getPlan(m,CURRENT_MONTH)||(m.plans||[]).find(p=>p.status!=='deferred');detailState.planMonth=plan?.month||null;els.detailPlanTitle.textContent=plan?'修改观影计划':'加入观影计划';els.detailPlanDate.value=plan?.plannedDate||localToday();els.detailPlanCurrent.classList.toggle('hidden',!plan);els.detailPlanCurrent.textContent=plan?`当前计划时间：${plan.plannedDate||plan.month+'（未指定日期）'}`:'';els.detailPlanClear.classList.toggle('hidden',!plan);els.detailPlanSave.textContent=plan?'保存新时间':'加入计划';els.detailPlanDialog.showModal()}
  function saveDetailPlan(){const m=currentDetailMovie();if(!m)return;const date=els.detailPlanDate.value||localToday(),month=date.slice(0,7);m.plans=m.plans||[];const current=detailState.planMonth?m.plans.find(p=>p.month===detailState.planMonth):null;if(current&&current.month!==month)m.plans=m.plans.filter(p=>p!==current);let plan=m.plans.find(p=>p.month===month);if(plan){plan.status='planned';plan.plannedDate=date;plan.movedTo=null}else m.plans.push({month,status:'planned',plannedDate:date,movedTo:null});detailState.planMonth=null;m.updatedAt=new Date().toISOString();save();renderAll();renderDetail();els.detailPlanDialog.close();toastMsg(`已安排在 ${date} 观看《${m.info.title}》`)}
